describe('Onboarding Tour Modal', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="start-onboarding-btn"]').click();
    cy.get('[data-testid="onboarding-modal"]').should('be.visible');
  });

  it('should advance through onboarding steps sequentially', () => {
    // Step 1: Verify first step is displayed
    cy.get('[data-testid="onboarding-step"]').should('contain', 'Welcome');
    cy.get('[data-testid="step-indicator"]').should('contain', '1 of 3');

    // Click next button to advance to step 2
    cy.get('[data-testid="next-btn"]').click();
    cy.get('[data-testid="onboarding-step"]').should('contain', 'Features');
    cy.get('[data-testid="step-indicator"]').should('contain', '2 of 3');

    // Click next button to advance to step 3
    cy.get('[data-testid="next-btn"]').click();
    cy.get('[data-testid="onboarding-step"]').should('contain', 'Get Started');
    cy.get('[data-testid="step-indicator"]').should('contain', '3 of 3');

    // Verify finish button appears on last step
    cy.get('[data-testid="finish-btn"]').should('be.visible');
    cy.get('[data-testid="next-btn"]').should('not.exist');
  });

  it('should navigate backwards through steps using previous button', () => {
    // Advance to step 2
    cy.get('[data-testid="next-btn"]').click();
    cy.get('[data-testid="onboarding-step"]').should('contain', 'Features');

    // Advance to step 3
    cy.get('[data-testid="next-btn"]').click();
    cy.get('[data-testid="onboarding-step"]').should('contain', 'Get Started');

    // Go back to step 2
    cy.get('[data-testid="prev-btn"]').click();
    cy.get('[data-testid="onboarding-step"]').should('contain', 'Features');
    cy.get('[data-testid="step-indicator"]').should('contain', '2 of 3');

    // Go back to step 1
    cy.get('[data-testid="prev-btn"]').click();
    cy.get('[data-testid="onboarding-step"]').should('contain', 'Welcome');
    cy.get('[data-testid="step-indicator"]').should('contain', '1 of 3');

    // Verify previous button is disabled on first step
    cy.get('[data-testid="prev-btn"]').should('be.disabled');
  });

  it('should close modal when finish button is clicked', () => {
    // Navigate to final step
    cy.get('[data-testid="next-btn"]').click();
    cy.get('[data-testid="next-btn"]').click();

    // Click finish button
    cy.get('[data-testid="finish-btn"]').click();

    // Verify modal is closed
    cy.get('[data-testid="onboarding-modal"]').should('not.be.visible');
  });

  it('should close modal when close icon is clicked', () => {
    // Click close button
    cy.get('[data-testid="close-modal-btn"]').click();

    // Verify modal is closed
    cy.get('[data-testid="onboarding-modal"]').should('not.be.visible');
  });

  it('should display correct content for each step', () => {
    // Step 1 content validation
    cy.get('[data-testid="step-title"]').should('have.text', 'Welcome to Our App');
    cy.get('[data-testid="step-description"]').should('contain', 'This is a guided tour');
    cy.get('[data-testid="step-image"]').should('have.attr', 'src').and('include', 'welcome');

    // Step 2 content validation
    cy.get('[data-testid="next-btn"]').click();
    cy.get('[data-testid="step-title"]').should('have.text', 'Explore Features');
    cy.get('[data-testid="step-description"]').should('contain', 'Discover what you can do');
    cy.get('[data-testid="step-image"]').should('have.attr', 'src').and('include', 'features');

    // Step 3 content validation
    cy.get('[data-testid="next-btn"]').click();
    cy.get('[data-testid="step-title"]').should('have.text', 'Ready to Begin');
    cy.get('[data-testid="step-description"]').should('contain', 'Start using the app');
    cy.get('[data-testid="step-image"]').should('have.attr', 'src').and('include', 'start');
  });
});
